import math

def get_angle(point):
    x, y = point
    return math.atan2(y, x)

def process_points(points, task):
    if task == "sort_close_to_y_axis":
        return sorted(points, key=lambda p: (abs(p[0]), get_angle(p)))
    elif task == "closest_point_to_origin":
        return min(points, key=lambda p: (abs(p[0]) + abs(p[1]), get_angle(p)))
    elif task == "group_by_quadrant":
        result = {}
        for p in points:
            x, y = p
            if x > 0 and y > 0:
                quad = 1
            elif x < 0 and y > 0:
                quad = 2
            elif x < 0 and y < 0:
                quad = 3
            else:
                quad = 4
            result.setdefault(quad, set()).add(p)
        return result
